#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
typedef array<array<ull,2>,2> Mat;
ull MOD;
Mat mul(const Mat&a, const Mat&b){
    Mat c={{{0,0},{0,0}}};
    for(int i=0;i<2;i++)for(int j=0;j<2;j++){
        ull s=0;
        for(int k=0;k<2;k++) s += a[i][k]*b[k][j];
        c[i][j]=s%MOD;
    }
    return c;
}
Mat matpow(Mat a, unsigned long long e){
    Mat r={{{1,0},{0,1}}};
    while(e){
        if(e&1) r=mul(r,a);
        a=mul(a,a);
        e>>=1;
    }
    return r;
}
int main(){
    long long n; int m;
    while(cin>>n>>m){
        MOD = 1ULL<<m;
        if(n==0){ cout<<0<<"\n"; continue; }
        Mat base={{{1,1},{1,0}}};
        Mat r = matpow(base, (unsigned long long)(n-1));
        cout << (r[0][0] % MOD) << "\n";
    }
}

